SET ROLE postgres;
SELECT lab.check('privacy readiness follows both installed hook and count bridge',(SELECT privacy_integration_ready FROM rtn_private.rollout_state)
 AND position('rtn_private.erase_account_links(u,j.id)' IN pg_get_functiondef('public.account_deletion_erase_data(uuid,text)'::regprocedure))
 <position('DELETE FROM public.profiles' IN pg_get_functiondef('public.account_deletion_erase_data(uuid,text)'::regprocedure))
 AND position('rtn_private.personal_counts(p_user)' IN pg_get_functiondef('public.uc_scoped_journal_personal_counts(uuid)'::regprocedure))>0);
