 SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN(VALUES('anon'),('authenticated'),('service_role'),('sandbox_exec_atxwvjxbqjgkbjlhsdch'))r(name)
 WHERE n.nspname='rtn_private' AND p.proname IN('lock_actor','erasure_allowed','personal_counts','organization_retention_count','allowed_redaction','personal_link_guard','erase_account_links') AND has_function_privilege(r.name,p.oid,'EXECUTE')));
